"use client";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, BookOpen, CalendarDays, ChevronRight, FileText, GraduationCap, Image as ImageIcon, LayoutDashboard, LockKeyhole, LogOut, Mail, Menu, Plus, Search, Save, Settings2, Shield, ShieldCheck, UserCheck, Users, Upload, Trash2, X } from "lucide-react";
import { createClient } from "@/lib/supabase/client";

type RoleKey = "super_administrator" | "school_administrator" | "language_school_manager" | "content_editor";
type StatusKey = "active" | "invited" | "suspended";
type Profile = { id:string; display_name:string|null; email:string; role:RoleKey; status:StatusKey; last_seen_at?:string|null };
type Permission = { role:RoleKey; permission_key:string; enabled:boolean };
type Audit = { id:string; action:string; created_at:string; metadata:Record<string,unknown>; target_user_id:string|null; actor_user_id:string|null };
type ContentPage = {slug:string;title:string;body:string;status:"draft"|"published";updated_at:string};
type Enquiry = {id:string;parent_name:string;email:string;phone:string;child_name:string|null;class_interest:string;message:string;status:string;created_at:string};
type Programme = {id:string;title:string;language:string;description:string;status:"draft"|"published"};
type MediaAsset = {id:string;storage_path:string;file_name:string;alt_text:string;caption:string;category:"Learning"|"Creativity"|"Community";is_published:boolean;created_at:string};
type SchoolSettings = {school_name:string;motto:string;phone:string;alternate_phone:string;email:string;website:string;address:string;current_academic_year:string;current_term:string;term_start:string;term_end:string;holiday_start:string;holiday_end:string;facebook:string;instagram:string;youtube:string;linkedin:string;logo_url:string;favicon_url:string};
const emptySchoolSettings:SchoolSettings={school_name:"",motto:"",phone:"",alternate_phone:"",email:"",website:"",address:"",current_academic_year:"",current_term:"",term_start:"",term_end:"",holiday_start:"",holiday_end:"",facebook:"",instagram:"",youtube:"",linkedin:"",logo_url:"",favicon_url:""};
const roleLabels:Record<RoleKey,string>={super_administrator:"Super Administrator",school_administrator:"School Administrator",language_school_manager:"Language School Manager",content_editor:"Content Editor"};
const statusLabels:Record<StatusKey,string>={active:"Active",invited:"Invited",suspended:"Suspended"};
const nav=[{label:"Overview",icon:LayoutDashboard},{label:"Staff accounts",icon:Users},{label:"Role permissions",icon:ShieldCheck},{label:"Activity log",icon:Activity},{label:"Content & pages",icon:FileText},{label:"Media library",icon:ImageIcon},{label:"Homepage editor",icon:FileText},{label:"Admissions",icon:GraduationCap},{label:"Language school",icon:BookOpen},{label:"Settings",icon:Settings2}];
const labelFor=(key:string)=>key.split(".").map(x=>x.replace(/_/g," ")).join(" · ").replace(/\b\w/g,c=>c.toUpperCase());
const timeAgo=(value?:string|null)=>{if(!value)return "No sign-in yet";const diff=Math.max(0,Date.now()-new Date(value).getTime());const mins=Math.floor(diff/60000);if(mins<1)return "Just now";if(mins<60)return mins+" min ago";if(mins<1440)return Math.floor(mins/60)+" hours ago";return Math.floor(mins/1440)+" days ago";};
export default function DashboardClient({initialProfile}:{initialProfile:Profile}) {
 const supabase=useMemo(()=>createClient(),[]);
 const [section,setSection]=useState(initialProfile.role==="super_administrator"?"Overview":"Media library"),[staff,setStaff]=useState<Profile[]>([]),[permissions,setPermissions]=useState<Permission[]>([]),[logs,setLogs]=useState<Audit[]>([]);
 const [search,setSearch]=useState(""),[filter,setFilter]=useState("all"),[invite,setInvite]=useState(false),[mobile,setMobile]=useState(false),[busy,setBusy]=useState(false),[notice,setNotice]=useState(""),[error,setError]=useState("");
 const [pages,setPages]=useState<ContentPage[]>([]),[enquiries,setEnquiries]=useState<Enquiry[]>([]),[programmes,setProgrammes]=useState<Programme[]>([]),[media,setMedia]=useState<MediaAsset[]>([]);
 const [schoolSettings,setSchoolSettings]=useState<SchoolSettings>(emptySchoolSettings);
 const [homepageContent,setHomepageContent]=useState<Record<string,string>>({});
 const [mediaFile,setMediaFile]=useState<File|null>(null),[mediaAlt,setMediaAlt]=useState(""),[mediaCaption,setMediaCaption]=useState(""),[mediaCategory,setMediaCategory]=useState<MediaAsset["category"]>("Learning"),[editingMedia,setEditingMedia]=useState<MediaAsset|null>(null),[editAlt,setEditAlt]=useState(""),[editCaption,setEditCaption]=useState(""),[editCategory,setEditCategory]=useState<MediaAsset["category"]>("Learning");
 const [contentSlug,setContentSlug]=useState(""),[contentTitle,setContentTitle]=useState(""),[contentBody,setContentBody]=useState(""),[programTitle,setProgramTitle]=useState(""),[programLanguage,setProgramLanguage]=useState(""),[programDescription,setProgramDescription]=useState("");
 const [name,setName]=useState(""),[email,setEmail]=useState(""),[role,setRole]=useState<RoleKey>("school_administrator"),[permissionRole,setPermissionRole]=useState<RoleKey>("school_administrator");
 const load=useCallback(async()=>{
  setBusy(true);setError("");
  if(initialProfile.role!=="super_administrator"){const {data,error}=await supabase.from("media_assets").select("id,storage_path,file_name,alt_text,caption,category,is_published,created_at").order("created_at",{ascending:false});if(error)setError(error.message);else setMedia((data||[]) as MediaAsset[]);setBusy(false);return;}
  const [s,p,a]=await Promise.all([
   supabase.from("staff_profiles").select("id,display_name,email,role,status,last_seen_at").order("created_at",{ascending:false}),
   supabase.from("role_permissions").select("role,permission_key,enabled").order("role").order("permission_key"),
   supabase.from("staff_audit_logs").select("id,action,created_at,metadata,target_user_id,actor_user_id").order("created_at",{ascending:false}).limit(40)
  ]);
  if(s.error)setError(s.error.message);else setStaff((s.data||[]) as Profile[]);
  if(p.error)setError(p.error.message);else setPermissions((p.data||[]) as Permission[]);
  if(a.error)setError(a.error.message);else setLogs((a.data||[]) as Audit[]);
  const extra = await Promise.all([
    supabase.from("site_content").select("slug,title,body,status,updated_at").order("updated_at",{ascending:false}),
    supabase.from("admissions_enquiries").select("id,parent_name,email,phone,child_name,class_interest,message,status,created_at").order("created_at",{ascending:false}).limit(100),
    supabase.from("language_programmes").select("id,title,language,description,status").order("created_at",{ascending:false}),
    supabase.from("media_assets").select("id,storage_path,file_name,alt_text,caption,category,is_published,created_at").order("created_at",{ascending:false}),
    supabase.from("site_settings").select("setting_key,setting_value").in("setting_key",["school_profile","homepage_content"])
  ]);
  if(!extra[0].error)setPages((extra[0].data||[]) as ContentPage[]);
  if(!extra[1].error)setEnquiries((extra[1].data||[]) as Enquiry[]);
  if(!extra[2].error)setProgrammes((extra[2].data||[]) as Programme[]);
  if(!extra[3].error)setMedia((extra[3].data||[]) as MediaAsset[]);
  if(!extra[4].error){const settings=(extra[4].data||[]) as {setting_key:string;setting_value:Record<string,string>}[];const saved=settings.find(x=>x.setting_key==="school_profile")?.setting_value||{};setSchoolSettings({...emptySchoolSettings,...saved});setHomepageContent(settings.find(x=>x.setting_key==="homepage_content")?.setting_value||{});}
  setBusy(false);
 },[supabase,initialProfile.role]);
 useEffect(()=>{void load();},[load]);
 const visibleNav=initialProfile.role==="super_administrator"?nav:nav.filter(x=>x.label==="Media library");
 const rows=staff.filter(x=>((x.display_name||"")+" "+x.email).toLowerCase().includes(search.toLowerCase())&&(filter==="all"||x.status===filter));
 const active=staff.filter(x=>x.status==="active").length,pending=staff.filter(x=>x.status==="invited").length,suspended=staff.filter(x=>x.status==="suspended").length;
 const act=async(action:string,payload:Record<string,unknown>)=>{
  setBusy(true);setError("");setNotice("");
  const {data,error}=await supabase.functions.invoke("manage-staff",{body:{action,...payload}});
  setBusy(false);
  if(error||data?.error){setError(data?.error||error?.message||"The request failed.");return;}
  setNotice("Changes saved successfully.");await load();
 };
 const sendInvite=async(e:React.FormEvent)=>{
  e.preventDefault();setBusy(true);setError("");setNotice("");
  const {data,error}=await supabase.functions.invoke("invite-staff",{body:{email,display_name:name,role}});
  setBusy(false);
  if(error||data?.error){setError(data?.error||error?.message||"Invitation could not be sent.");return;}
  setNotice("Invitation sent to "+email+".");setInvite(false);setName("");setEmail("");await load();
 };
 const saveContent=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");const {error}=await supabase.from("site_content").upsert({slug:contentSlug.trim().toLowerCase(),title:contentTitle,body:contentBody,status:"draft",updated_by:initialProfile.id},{onConflict:"slug"});setBusy(false);if(error){setError(error.message);return;}setNotice("Page saved as a draft.");setContentSlug("");setContentTitle("");setContentBody("");await load();};
 const changeEnquiry=async(id:string,status:string)=>{setBusy(true);const {error}=await supabase.from("admissions_enquiries").update({status}).eq("id",id);setBusy(false);if(error)setError(error.message);else{setNotice("Admissions enquiry updated.");await load();}};
 const addProgramme=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);const {error}=await supabase.from("language_programmes").insert({title:programTitle,language:programLanguage,description:programDescription,status:"draft"});setBusy(false);if(error){setError(error.message);return;}setNotice("Language programme saved as a draft.");setProgramTitle("");setProgramLanguage("");setProgramDescription("");await load();};
 const publishContent=async(slug:string,status:"draft"|"published")=>{setBusy(true);const {error}=await supabase.from("site_content").update({status,updated_by:initialProfile.id}).eq("slug",slug);setBusy(false);if(error)setError(error.message);else{setNotice("Page visibility updated.");await load();}};
 const updateSchoolSetting=(key:keyof SchoolSettings,value:string)=>setSchoolSettings(current=>({...current,[key]:value}));
 const updateHomepageContent=(key:string,value:string)=>setHomepageContent(current=>({...current,[key]:value}));
 const saveHomepageContent=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");setNotice("");const {error}=await supabase.from("site_settings").upsert({setting_key:"homepage_content",setting_value:homepageContent,updated_by:initialProfile.id},{onConflict:"setting_key"});setBusy(false);if(error){setError("Homepage content could not be saved: "+error.message);return;}setNotice("Homepage changes saved and published.");await load();};
 const saveSchoolSettings=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");setNotice("");const {error}=await supabase.from("site_settings").upsert({setting_key:"school_profile",setting_value:schoolSettings,updated_by:initialProfile.id},{onConflict:"setting_key"});setBusy(false);if(error){setError("School settings could not be saved: "+error.message);return;}setNotice("School settings saved securely. These details remain unpublished until connected to approved website sections.");await load();};
 const uploadMedia=async(e:React.FormEvent)=>{e.preventDefault();if(!mediaFile)return;if(!["image/jpeg","image/png","image/webp","image/avif"].includes(mediaFile.type)){setError("Choose a JPEG, PNG, WebP or AVIF image.");return;}if(mediaFile.size>10*1024*1024){setError("Image must be 10 MB or smaller.");return;}if(!mediaAlt.trim()){setError("Alternative text is required.");return;}setBusy(true);setError("");setNotice("");const safeName=mediaFile.name.toLowerCase().replace(/[^a-z0-9.-]+/g,"-");const path=`${Date.now()}-${crypto.randomUUID()}-${safeName}`;const {error:uploadError}=await supabase.storage.from("school-media").upload(path,mediaFile,{contentType:mediaFile.type,upsert:false,cacheControl:"3600"});if(uploadError){setBusy(false);setError(uploadError.message);return;}const {error:recordError}=await supabase.from("media_assets").insert({storage_path:path,file_name:mediaFile.name,alt_text:mediaAlt,caption:mediaCaption,category:mediaCategory,created_by:initialProfile.id});if(recordError){await supabase.storage.from("school-media").remove([path]);setBusy(false);setError(recordError.message);return;}setMediaFile(null);setMediaAlt("");setMediaCaption("");setNotice("Image uploaded and saved as an unpublished media item.");setBusy(false);await load();};
 const saveMediaDetails=async(e:React.FormEvent)=>{e.preventDefault();if(!editingMedia)return;setBusy(true);setError("");const {error}=await supabase.from("media_assets").update({alt_text:editAlt.trim(),caption:editCaption.trim(),category:editCategory}).eq("id",editingMedia.id);setBusy(false);if(error){setError(error.message);return;}setNotice("Image details updated.");setEditingMedia(null);await load();};
 const toggleMedia=async(item:MediaAsset)=>{setBusy(true);const {error}=await supabase.from("media_assets").update({is_published:!item.is_published}).eq("id",item.id);setBusy(false);if(error)setError(error.message);else{setNotice(item.is_published?"Image unpublished.":"Image published to the school gallery.");await load();}};
 const deleteMedia=async(item:MediaAsset)=>{if(!window.confirm("Permanently delete this image? This cannot be undone."))return;setBusy(true);const {error:storageError}=await supabase.storage.from("school-media").remove([item.storage_path]);if(storageError){setBusy(false);setError(storageError.message);return;}const {error}=await supabase.from("media_assets").delete().eq("id",item.id);setBusy(false);if(error)setError(error.message);else{setNotice("Image deleted.");await load();}};
 const mediaUrl=(path:string)=>supabase.storage.from("school-media").getPublicUrl(path).data.publicUrl;
 const signOut=async()=>{await supabase.auth.signOut();window.location.assign("/login");};
 const heading:Record<string,string>={"Overview":"Good morning, team","Homepage editor":"Homepage content editor","Staff accounts":"Staff accounts","Role permissions":"Role permissions","Activity log":"Activity & audit log","Content & pages":"Content & pages","Media library":"School media library","Admissions":"Admissions workspace","Language school":"Language school","Settings":"Workspace settings"};
 const grouped=permissions.filter(p=>p.role===permissionRole);
 const eventTitle=(a:string)=>a.replace(/[._]/g," ").replace(/\b\w/g,c=>c.toUpperCase());
 return <div className="min-h-screen bg-[#f8f7fa]">
 <div className={"fixed inset-0 z-40 bg-black/40 lg:hidden "+(mobile?"block":"hidden")} onClick={()=>setMobile(false)}/>
 <aside className={"fixed inset-y-0 left-0 z-50 flex w-[258px] flex-col bg-[#291640] px-4 py-5 text-white transition-transform lg:translate-x-0 "+(mobile?"translate-x-0":"-translate-x-full")}>
  <div className="flex items-center gap-3 px-2 pb-8"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f4c542] text-xl font-black text-[#291640]">J</div><div><b className="text-[15px] tracking-wide">JUNEBERRIES</b><p className="text-[10px] tracking-[.22em] text-purple-200">SCHOOLS · ADMIN</p></div><button className="ml-auto lg:hidden" onClick={()=>setMobile(false)}><X size={18}/></button></div>
  <div className="mb-5 rounded-xl border border-white/10 bg-white/[.07] p-3"><div className="flex items-center gap-2 text-xs font-semibold"><Shield size={15} className="text-[#f4c542]"/> Administration portal</div><p className="mt-1 pl-6 text-[10px] text-purple-200">Secure staff workspace</p></div>
  <nav className="flex-1 space-y-1">{visibleNav.map(({label,icon:Icon},i)=><button key={label} onClick={()=>{setSection(label);setMobile(false)}} className={"navitem "+(section===label?"active":"")+(i===4?" mt-5":"")}><Icon size={16}/>{label}{label==="Staff accounts"&&<span className="ml-auto rounded-full bg-white/10 px-2 py-0.5 text-[10px]">{staff.length.toString().padStart(2,"0")}</span>}</button>)}</nav>
  <div className="rounded-xl border border-white/10 bg-white/[.06] p-3"><div className="flex items-center gap-2"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#f4c542] text-xs font-bold text-[#291640]">SA</div><div className="min-w-0"><p className="truncate text-xs font-semibold">{initialProfile.display_name||initialProfile.email}</p><p className="text-[10px] text-purple-200">{roleLabels[initialProfile.role]}</p></div><button onClick={signOut} title="Sign out" className="ml-auto text-purple-200"><LogOut size={16}/></button></div></div>
 </aside>
 <div className="min-h-screen lg:pl-[258px]">
 <header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur-xl sm:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMobile(true)} className="rounded-lg p-2 text-slate-600 lg:hidden"><Menu size={20}/></button><div className="hidden items-center gap-2 text-xs text-slate-400 sm:flex">Juneberries <ChevronRight size={13}/><b className="text-slate-700">{section}</b></div><b className="text-sm sm:hidden">Juneberries Admin</b></div><div className="flex items-center gap-3"><span className="hidden text-xs text-slate-500 md:block">{initialProfile.email}</span><button onClick={load} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold">{busy?"Refreshing…":"Refresh data"}</button><button onClick={signOut} className="rounded-lg p-2 text-slate-500" title="Sign out"><LogOut size={17}/></button></div></header>
 <main className="mx-auto max-w-[1500px] px-4 py-7 sm:px-7 lg:px-9">
 <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.17em] text-[#693b9c]">✦ JUNEBERRIES SCHOOLS · ADMINISTRATION</div><h1 className="text-[27px] font-bold tracking-tight text-[#211a2b] sm:text-[31px]">{heading[section]||section}</h1><p className="mt-1.5 text-sm text-slate-500">{section==="Overview"?"Live view of authorised school staff and administration activity.":"Manage access, responsibilities and school operations in one place."}</p></div><div className="flex items-center gap-2 text-xs text-slate-500"><CalendarDays size={15}/>{new Date().toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric"})}</div></div>
 <div className="mb-5 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs leading-5 text-emerald-900"><b>Connected to Juneberries Supabase:</b> {initialProfile.role==="super_administrator"?"Live account, permission and audit records.":"Media library access is limited by your assigned staff permissions."}</div>
 {notice&&<div className="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs text-emerald-800">{notice}</div>}{error&&<div role="alert" className="mb-4 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-xs text-rose-800">{error}</div>}
 {section==="Overview"&&<><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{label:"Total staff accounts",value:staff.length,Icon:Users,sub:"All assigned roles"},{label:"Active accounts",value:active,Icon:UserCheck,sub:"Currently authorised"},{label:"Pending invitations",value:pending,Icon:Mail,sub:"Awaiting acceptance"},{label:"Suspended accounts",value:suspended,Icon:LockKeyhole,sub:"Access restricted"}].map(card=><div className="panel p-5" key={card.label}><div className="flex items-center justify-between text-xs text-slate-500">{card.label}<span className="grid h-9 w-9 place-items-center rounded-xl bg-[#f8f5fc] text-[#693b9c]"><card.Icon size={17}/></span></div><p className="mt-3 text-[29px] font-bold">{card.value.toString().padStart(2,"0")}</p><p className="mt-1 text-[11px] text-slate-400">{card.sub}</p></div>)}</div>
 <div className="mt-6 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><section className="panel p-5 sm:p-6"><div className="flex justify-between"><div><h2 className="text-sm font-bold">Staff directory</h2><p className="mt-1 text-xs text-slate-400">Live staff accounts and access status.</p></div><button onClick={()=>setSection("Staff accounts")} className="text-xs font-semibold text-[#693b9c]">View all <ChevronRight size={13} className="inline"/></button></div><div className="mt-5 space-y-4">{staff.slice(0,5).map(x=><div className="flex items-center gap-3" key={x.id}><div className="grid h-9 w-9 place-items-center rounded-full bg-[#eee7f7] text-[11px] font-bold text-[#542d80]">{(x.display_name||x.email).split(" ").map(a=>a[0]).join("").slice(0,2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{x.display_name||"Staff member"}</p><p className="mt-0.5 text-[10px] text-slate-400">{roleLabels[x.role]}</p></div><Status status={x.status}/></div>)}</div>{!staff.length&&<p className="py-8 text-center text-xs text-slate-400">No staff profiles have been provisioned yet.</p>}</section>
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Recent activity</h2><p className="mt-1 text-xs text-slate-400">Latest administrative events.</p><div className="mt-5 space-y-5">{logs.slice(0,5).map(e=><div className="flex gap-3" key={e.id}><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#f8f5fc] text-[#693b9c]"><Activity size={15}/></span><div><p className="text-xs font-semibold">{eventTitle(e.action)}</p><p className="mt-1 text-[10px] text-slate-500">{e.metadata?.email?String(e.metadata.email):e.target_user_id||"Workspace event"}</p><p className="mt-1 text-[10px] text-slate-400">{new Date(e.created_at).toLocaleString()}</p></div></div>)}</div><button onClick={()=>setSection("Activity log")} className="mt-5 text-xs font-semibold text-[#693b9c]">Open activity log <ChevronRight size={13} className="inline"/></button></section></div>
 <section className="panel mt-5 p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-bold">Access governance</h2><p className="mt-1 text-xs text-slate-400">Four approved roles with distinct responsibilities.</p></div><button onClick={()=>setSection("Role permissions")} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold">Review permissions <ChevronRight size={13} className="inline"/></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{Object.entries(roleLabels).map(([r,label],i)=><div key={r} className="rounded-xl border border-slate-100 bg-slate-50/70 p-4"><div className="mb-3 grid h-9 w-9 place-items-center rounded-xl bg-white text-[#693b9c]">{i===0?<ShieldCheck size={17}/>:i===1?<Users size={17}/>:i===2?<BookOpen size={17}/>:<FileText size={17}/>}</div><p className="text-xs font-bold">{label}</p><p className="mt-1 text-[10px] leading-4 text-slate-500">{["Full governance and staff oversight","School-wide administration","Language school operations","Website content and media"][i]}</p></div>)}</div></section></>}
 {section==="Staff accounts"&&<section className="panel p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="text-sm font-bold">All staff accounts <span className="ml-1 rounded-full bg-slate-100 px-2 py-0.5 text-[10px] text-slate-500">{staff.length}</span></h2><p className="mt-1 text-xs text-slate-400">Invite colleagues and manage their account access.</p></div><button onClick={()=>setInvite(true)} className="rounded-xl bg-[#542d80] px-4 py-2.5 text-xs font-semibold text-white"><Plus size={15} className="mr-1 inline"/> Invite staff</button></div><div className="mt-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-3 text-slate-400"/><input className="field pl-9" placeholder="Search by name or email..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select className="field sm:w-44" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All statuses</option><option value="active">Active</option><option value="invited">Invited</option><option value="suspended">Suspended</option></select></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-slate-100 text-[10px] uppercase tracking-wider text-slate-400"><th className="pb-3">Staff member</th><th className="pb-3">Assigned role</th><th className="pb-3">Status</th><th className="pb-3">Last activity</th><th className="pb-3 text-right">Actions</th></tr></thead><tbody>{rows.map(x=><tr key={x.id} className="border-b border-slate-50 last:border-0"><td className="py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-[#eee7f7] text-[10px] font-bold text-[#542d80]">{(x.display_name||x.email).split(" ").map(a=>a[0]).join("").slice(0,2).toUpperCase()}</div><div><p className="text-xs font-semibold">{x.display_name||"Staff member"}</p><p className="mt-1 text-[10px] text-slate-400">{x.email}</p></div></div></td><td className="py-4 text-xs text-slate-600">{roleLabels[x.role]}</td><td className="py-4"><Status status={x.status}/></td><td className="py-4 text-xs text-slate-500">{timeAgo(x.last_seen_at)}</td><td className="py-4 text-right"><div className="flex justify-end gap-2"><select aria-label={"Change role for "+x.email} disabled={x.role==="super_administrator"||busy} value={x.role} onChange={e=>void act("change_role",{user_id:x.id,role:e.target.value})} className="max-w-[170px] rounded-lg border border-slate-200 px-2 py-1.5 text-[10px]">{Object.entries(roleLabels).filter(([key])=>key!=="super_administrator").map(([key,label])=><option key={key} value={key}>{label}</option>)}</select>{x.role!=="super_administrator"&&<button disabled={busy||x.status==="invited"} onClick={()=>void act(x.status==="suspended"?"reactivate":"suspend",{user_id:x.id})} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] font-semibold disabled:opacity-40">{x.status==="suspended"?"Reactivate":"Suspend"}</button>}</div></td></tr>)}</tbody></table>{rows.length===0&&<p className="py-10 text-center text-xs text-slate-400">No matching accounts.</p>}</div></section>}
 {section==="Role permissions"&&<section className="panel p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-sm font-bold">Role permission matrix</h2><p className="mt-1 text-xs text-slate-400">Changes are saved through the Super Administrator Edge Function.</p></div><select className="field max-w-[240px]" value={permissionRole} onChange={e=>setPermissionRole(e.target.value as RoleKey)}>{Object.entries(roleLabels).filter(([r])=>r!=="super_administrator").map(([r,l])=><option value={r} key={r}>{l}</option>)}</select></div><div className="mt-5 divide-y divide-slate-100">{grouped.map(p=><div key={p.permission_key} className="flex items-center justify-between gap-3 py-4"><div><p className="text-xs font-semibold">{labelFor(p.permission_key)}</p><p className="mt-1 text-[10px] text-slate-400">{p.permission_key}</p></div><button disabled={busy} aria-label={"Toggle "+p.permission_key} onClick={()=>void act("update_permission",{role:p.role,permission_key:p.permission_key,enabled:!p.enabled})} className={"relative h-7 w-12 rounded-full transition "+(p.enabled?"bg-[#542d80]":"bg-slate-200")}><span className={"absolute top-1 h-5 w-5 rounded-full bg-white shadow transition "+(p.enabled?"left-6":"left-1")}/></button></div>)}</div>{grouped.length===0&&<p className="py-10 text-center text-xs text-slate-400">No permissions are configured for this role.</p>}<p className="mt-5 rounded-xl border border-[#ddcfee] bg-[#f8f5fc] p-4 text-xs leading-5 text-[#3d205f]"><ShieldCheck size={15} className="mr-2 inline"/> Super Administrator governance rights are fixed and cannot be changed here.</p></section>}
 {section==="Activity log"&&<section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Administrative activity</h2><p className="mt-1 text-xs text-slate-400">Audit events retrieved directly from Supabase.</p><div className="mt-5">{logs.map(e=><div key={e.id} className="flex flex-wrap gap-4 border-b border-slate-100 py-5 last:border-0"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f8f5fc] text-[#693b9c]"><Activity size={17}/></span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{eventTitle(e.action)}</p><p className="mt-1 text-xs text-slate-500">{JSON.stringify(e.metadata||{})}</p><p className="mt-1 text-[10px] text-slate-400">Actor: {e.actor_user_id||"System"} · Target: {e.target_user_id||"—"}</p></div><span className="whitespace-nowrap text-[10px] text-slate-400">{new Date(e.created_at).toLocaleString()}</span></div>)}</div></section>}
 {section==="Content & pages"&&<div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><section className="panel p-5"><h2 className="text-sm font-bold">Create or update a page</h2><p className="mt-1 text-xs text-slate-400">Save editable website content as a draft.</p><form onSubmit={saveContent} className="mt-5 space-y-3"><label className="block text-xs font-semibold">Page slug<input className="field mt-2" required pattern="[a-z0-9-]+" placeholder="about-our-school" value={contentSlug} onChange={e=>setContentSlug(e.target.value)}/></label><label className="block text-xs font-semibold">Page title<input className="field mt-2" required value={contentTitle} onChange={e=>setContentTitle(e.target.value)}/></label><label className="block text-xs font-semibold">Page content<textarea className="field mt-2 min-h-40" required value={contentBody} onChange={e=>setContentBody(e.target.value)}/></label><button disabled={busy} className="rounded-xl bg-[#542d80] px-4 py-3 text-xs font-semibold text-white">Save draft</button></form></section><section className="panel p-5"><h2 className="text-sm font-bold">Website pages</h2><p className="mt-1 text-xs text-slate-400">Draft and published content records.</p><div className="mt-4 space-y-3">{pages.map(p=><div key={p.slug} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-semibold">{p.title}</p><p className="mt-1 text-[10px] text-slate-400">/{p.slug} · Updated {new Date(p.updated_at).toLocaleDateString()}</p></div><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-semibold">{p.status}</span></div><p className="mt-3 line-clamp-3 whitespace-pre-wrap text-xs leading-5 text-slate-500">{p.body}</p><button disabled={busy} onClick={()=>void publishContent(p.slug,p.status==="published"?"draft":"published")} className="mt-3 rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-semibold">{p.status==="published"?"Unpublish":"Publish"}</button></div>)}{!pages.length&&<p className="py-10 text-center text-xs text-slate-400">No CMS pages yet. Create your first draft.</p>}</div></section></div>}
 {section==="Media library"&&<div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><section className="panel p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f8f5fc] text-[#693b9c]"><Upload size={18}/></span><div><h2 className="text-sm font-bold">Upload school photographs</h2><p className="mt-1 text-xs text-slate-400">JPEG, PNG, WebP or AVIF · Maximum 10 MB</p></div></div><form onSubmit={uploadMedia} className="mt-5 space-y-4"><label className="block text-xs font-semibold">Choose image<input className="field mt-2 cursor-pointer" type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={e=>setMediaFile(e.target.files?.[0]||null)} required/></label>{mediaFile&&<p className="text-[11px] text-slate-500">{mediaFile.name} · {(mediaFile.size/1024/1024).toFixed(2)} MB</p>}<label className="block text-xs font-semibold">Alternative text<input className="field mt-2" value={mediaAlt} onChange={e=>setMediaAlt(e.target.value)} required maxLength={180} placeholder="Describe what is visible in the photograph"/></label><label className="block text-xs font-semibold">Caption<input className="field mt-2" value={mediaCaption} onChange={e=>setMediaCaption(e.target.value)} maxLength={180} placeholder="Optional short caption"/></label><label className="block text-xs font-semibold">Gallery category<select className="field mt-2" value={mediaCategory} onChange={e=>setMediaCategory(e.target.value as MediaAsset["category"])}><option>Learning</option><option>Creativity</option><option>Community</option></select></label><button disabled={busy||!mediaFile} className="w-full rounded-xl bg-[#542d80] px-4 py-3 text-xs font-semibold text-white disabled:opacity-50">{busy?"Uploading…":<><Upload size={14} className="mr-2 inline"/> Upload image</>}</button><p className="text-[10px] leading-5 text-slate-400">New uploads remain unpublished until an authorised editor chooses to publish them.</p></form></section><section className="panel p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold">Media library <span className="ml-1 rounded-full bg-slate-100 px-2 py-0.5 text-[10px]">{media.length}</span></h2><p className="mt-1 text-xs text-slate-400">Manage the photographs shown on the public school gallery.</p></div><button onClick={load} className="rounded-lg border border-slate-200 px-3 py-2 text-xs">Refresh</button></div>{editingMedia&&<form onSubmit={saveMediaDetails} className="mt-5 grid gap-3 rounded-xl border border-[#d9cde0] bg-[#faf8fc] p-4 sm:grid-cols-2"><div className="sm:col-span-2"><b className="text-xs">Edit image details</b><p className="mt-1 text-[10px] text-slate-500">{editingMedia.file_name}</p></div><label className="block text-xs font-semibold">Alternative text<input required maxLength={180} className="field mt-2" value={editAlt} onChange={e=>setEditAlt(e.target.value)}/></label><label className="block text-xs font-semibold">Caption<input maxLength={180} className="field mt-2" value={editCaption} onChange={e=>setEditCaption(e.target.value)}/></label><label className="block text-xs font-semibold">Category<select className="field mt-2" value={editCategory} onChange={e=>setEditCategory(e.target.value as MediaAsset["category"])}><option>Learning</option><option>Creativity</option><option>Community</option></select></label><div className="flex items-end gap-2"><button disabled={busy} className="rounded-lg bg-[#542d80] px-4 py-2.5 text-xs font-semibold text-white">Save changes</button><button type="button" onClick={()=>setEditingMedia(null)} className="rounded-lg border px-4 py-2.5 text-xs">Cancel</button></div></form>}<div className="mt-5 grid gap-4 sm:grid-cols-2">{media.map(item=><article key={item.id} className="overflow-hidden rounded-xl border border-slate-100 bg-white"><img src={mediaUrl(item.storage_path)} alt={item.alt_text} className="h-44 w-full object-cover" loading="lazy"/><div className="p-3"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="truncate text-xs font-semibold">{item.file_name}</p><p className="mt-1 text-[10px] text-slate-400">{item.category} · {new Date(item.created_at).toLocaleDateString()}</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${item.is_published?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}>{item.is_published?"Published":"Draft"}</span></div>{item.caption&&<p className="mt-2 text-[11px] text-slate-500">{item.caption}</p>}<p className="mt-2 text-[10px] leading-4 text-slate-400">Alt: {item.alt_text}</p><div className="mt-3 flex flex-wrap gap-2"><button disabled={busy} onClick={()=>{setEditingMedia(item);setEditAlt(item.alt_text);setEditCaption(item.caption);setEditCategory(item.category);}} className="rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-semibold">Edit</button><button disabled={busy} onClick={()=>void toggleMedia(item)} className="flex-1 rounded-lg border border-slate-200 px-2 py-2 text-[10px] font-semibold">{item.is_published?"Unpublish":"Publish"}</button><button disabled={busy} onClick={()=>void deleteMedia(item)} aria-label={"Delete "+item.file_name} className="rounded-lg border border-rose-100 px-3 py-2 text-rose-600"><Trash2 size={14}/></button></div></div></article>)}</div>{media.length===0&&<p className="py-12 text-center text-xs text-slate-400">No photographs uploaded yet. Add the first approved school image.</p>}</section></div>}
 {section==="Admissions"&&<section className="panel p-5"><h2 className="text-sm font-bold">Admissions enquiries</h2><p className="mt-1 text-xs text-slate-400">Enquiries submitted through the public admissions form will appear here.</p><div className="mt-5 space-y-3">{enquiries.map(q=><article key={q.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap justify-between gap-3"><div><p className="text-sm font-semibold">{q.parent_name} · {q.class_interest}</p><p className="mt-1 text-xs text-slate-500">{q.email} · {q.phone}</p><p className="mt-1 text-xs text-slate-500">Child: {q.child_name||"Not provided"}</p><p className="mt-2 text-xs leading-5 text-slate-600">{q.message}</p></div><div className="min-w-[140px]"><label className="text-[10px] font-semibold text-slate-500">Enquiry status<select className="field mt-1" value={q.status} onChange={e=>void changeEnquiry(q.id,e.target.value)}><option value="new">New</option><option value="contacted">Contacted</option><option value="in_review">In review</option><option value="closed">Closed</option></select></label></div></div><p className="mt-3 text-[10px] text-slate-400">{new Date(q.created_at).toLocaleString()}</p></article>)}{!enquiries.length&&<p className="py-10 text-center text-xs text-slate-400">No admissions enquiries received yet.</p>}</div></section>}
 {section==="Language school"&&<div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><section className="panel p-5"><h2 className="text-sm font-bold">Add a language programme</h2><form onSubmit={addProgramme} className="mt-5 space-y-3"><label className="block text-xs font-semibold">Programme title<input className="field mt-2" required value={programTitle} onChange={e=>setProgramTitle(e.target.value)}/></label><label className="block text-xs font-semibold">Language<input className="field mt-2" required value={programLanguage} onChange={e=>setProgramLanguage(e.target.value)}/></label><label className="block text-xs font-semibold">Description<textarea className="field mt-2 min-h-28" value={programDescription} onChange={e=>setProgramDescription(e.target.value)}/></label><button disabled={busy} className="rounded-xl bg-[#542d80] px-4 py-3 text-xs font-semibold text-white">Save programme draft</button></form></section><section className="panel p-5"><h2 className="text-sm font-bold">Language programmes</h2><div className="mt-4 space-y-3">{programmes.map(p=><div key={p.id} className="rounded-xl border border-slate-100 p-4"><div className="flex justify-between gap-2"><div><p className="text-sm font-semibold">{p.title}</p><p className="mt-1 text-xs text-slate-500">{p.language}</p></div><span className="text-[10px] text-slate-400">{p.status}</span></div><p className="mt-2 text-xs leading-5 text-slate-500">{p.description}</p></div>)}{!programmes.length&&<p className="py-10 text-center text-xs text-slate-400">No programmes created yet.</p>}</div></section></div>}
 {section==="Homepage editor"&&<form onSubmit={saveHomepageContent} className="space-y-5">
 <section className="panel p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-sm font-bold">Homepage content editor</h2><p className="mt-1 text-xs text-slate-400">Edit the words displayed on the public homepage. Leave a field blank to keep the current designed default.</p></div><span className="rounded-full bg-emerald-50 px-3 py-1.5 text-[10px] font-bold text-emerald-700">Super Administrator</span></div></section>
 {[
 {title:"Hero section",fields:[["hero_title","Main headline"],["hero_body","Introductory paragraph"]]},
 {title:"About Juneberries",fields:[["about_title","Section heading"],["about_body","First paragraph"],["about_body_2","Second paragraph"]]},
 {title:"Executive Director",fields:[["director_title","Section heading"],["director_message","Director's message"],["director_name","Director's name / title"]]},
 {title:"Our Team",fields:[["team_title","Section heading"],["team_intro","Introduction"]]},
 {title:"Language School",fields:[["language_title","Section heading"],["language_body","Description"]]},
 {title:"Gallery",fields:[["gallery_title","Section heading"],["gallery_intro","Introduction"]]},
 {title:"News & Events",fields:[["news_title","Section heading"]]}
 ].map(group=><section key={group.title} className="panel p-5 sm:p-6"><h3 className="text-sm font-bold">{group.title}</h3><div className="mt-4 grid gap-4 md:grid-cols-2">{group.fields.map(([key,label])=><label key={key} className="block text-xs font-semibold">{label}{key.endsWith("_body")||key.endsWith("_2")||key.endsWith("_message")||key.endsWith("_intro")?<textarea className="field mt-2 min-h-24" maxLength={1800} value={homepageContent[key]||""} onChange={e=>updateHomepageContent(key,e.target.value)} placeholder="Enter approved school content"/>:<input className="field mt-2" maxLength={220} value={homepageContent[key]||""} onChange={e=>updateHomepageContent(key,e.target.value)} placeholder="Enter approved text"/>}</label>)}</div></section>)}
 <section className="panel p-5 sm:p-6"><h3 className="text-sm font-bold">Homepage photographs</h3><p className="mt-1 text-xs text-slate-400">Choose an image already uploaded to the Media Library. Images remain managed there.</p><div className="mt-4 grid gap-4 md:grid-cols-2">{[["hero_image_path","Hero image"],["director_image_path","Executive Director portrait"]].map(([key,label])=><label key={key} className="block text-xs font-semibold">{label}<select className="field mt-2" value={homepageContent[key]||""} onChange={e=>updateHomepageContent(key,e.target.value)}><option value="">Use designed placeholder</option>{media.map(m=><option key={m.id} value={m.storage_path}>{m.file_name} · {m.is_published?"Published":"Draft"}</option>)}</select></label>)}</div></section>
 <div className="flex flex-wrap items-center justify-between gap-3"><p className="text-[11px] text-slate-400">Saving updates the public homepage content immediately. Review your text before saving.</p><button disabled={busy} className="rounded-xl bg-[#542d80] px-6 py-3 text-xs font-semibold text-white disabled:opacity-50">{busy?"Saving…":<><Save size={14} className="mr-2 inline"/> Save homepage changes</>}</button></div>
 </form>}
 {section==="Settings"&&<form onSubmit={saveSchoolSettings} className="space-y-5">
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">School identity</h2><p className="mt-1 text-xs text-slate-400">Official name and core brand statement.</p><div className="mt-4 grid gap-4 md:grid-cols-2">
 <label className="block text-xs font-semibold">Official school name<input className="field mt-2" value={schoolSettings.school_name} onChange={e=>updateSchoolSetting("school_name",e.target.value)} placeholder="Enter approved school name"/></label>
 <label className="block text-xs font-semibold">School motto / tagline<input className="field mt-2" value={schoolSettings.motto} onChange={e=>updateSchoolSetting("motto",e.target.value)} placeholder="Enter approved motto"/></label></div></section>
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Contact information</h2><p className="mt-1 text-xs text-slate-400">Only enter details verified by the school.</p><div className="mt-4 grid gap-4 md:grid-cols-2">
 <label className="block text-xs font-semibold">Main telephone<input className="field mt-2" type="tel" value={schoolSettings.phone} onChange={e=>updateSchoolSetting("phone",e.target.value)} placeholder="+234 ..."/></label>
 <label className="block text-xs font-semibold">Alternative telephone<input className="field mt-2" type="tel" value={schoolSettings.alternate_phone} onChange={e=>updateSchoolSetting("alternate_phone",e.target.value)} placeholder="Optional"/></label>
 <label className="block text-xs font-semibold">Official email<input className="field mt-2" type="email" value={schoolSettings.email} onChange={e=>updateSchoolSetting("email",e.target.value)} placeholder="school@example.com"/></label>
 <label className="block text-xs font-semibold">Website address<input className="field mt-2" type="url" value={schoolSettings.website} onChange={e=>updateSchoolSetting("website",e.target.value)} placeholder="https://..."/></label>
 <label className="block text-xs font-semibold md:col-span-2">School address<textarea className="field mt-2 min-h-20" value={schoolSettings.address} onChange={e=>updateSchoolSetting("address",e.target.value)} placeholder="Enter complete approved address"/></label></div></section>
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Academic calendar</h2><p className="mt-1 text-xs text-slate-400">Current academic year, term and holiday dates.</p><div className="mt-4 grid gap-4 md:grid-cols-2">
 <label className="block text-xs font-semibold">Academic year<input className="field mt-2" value={schoolSettings.current_academic_year} onChange={e=>updateSchoolSetting("current_academic_year",e.target.value)} placeholder="e.g. 2026/2027"/></label>
 <label className="block text-xs font-semibold">Current term<select className="field mt-2" value={schoolSettings.current_term} onChange={e=>updateSchoolSetting("current_term",e.target.value)}><option value="">Select term</option><option>First Term</option><option>Second Term</option><option>Third Term</option><option>Holiday</option></select></label>
 <label className="block text-xs font-semibold">Term start date<input className="field mt-2" type="date" value={schoolSettings.term_start} onChange={e=>updateSchoolSetting("term_start",e.target.value)}/></label>
 <label className="block text-xs font-semibold">Term end date<input className="field mt-2" type="date" value={schoolSettings.term_end} onChange={e=>updateSchoolSetting("term_end",e.target.value)}/></label>
 <label className="block text-xs font-semibold">Holiday begins<input className="field mt-2" type="date" value={schoolSettings.holiday_start} onChange={e=>updateSchoolSetting("holiday_start",e.target.value)}/></label>
 <label className="block text-xs font-semibold">School resumes<input className="field mt-2" type="date" value={schoolSettings.holiday_end} onChange={e=>updateSchoolSetting("holiday_end",e.target.value)}/></label></div></section>
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Social media profiles</h2><p className="mt-1 text-xs text-slate-400">Official public profile links.</p><div className="mt-4 grid gap-4 md:grid-cols-2">
 <label className="block text-xs font-semibold">Facebook<input className="field mt-2" type="url" value={schoolSettings.facebook} onChange={e=>updateSchoolSetting("facebook",e.target.value)} placeholder="https://facebook.com/..."/></label>
 <label className="block text-xs font-semibold">Instagram<input className="field mt-2" type="url" value={schoolSettings.instagram} onChange={e=>updateSchoolSetting("instagram",e.target.value)} placeholder="https://instagram.com/..."/></label>
 <label className="block text-xs font-semibold">YouTube<input className="field mt-2" type="url" value={schoolSettings.youtube} onChange={e=>updateSchoolSetting("youtube",e.target.value)} placeholder="https://youtube.com/..."/></label>
 <label className="block text-xs font-semibold">LinkedIn<input className="field mt-2" type="url" value={schoolSettings.linkedin} onChange={e=>updateSchoolSetting("linkedin",e.target.value)} placeholder="https://linkedin.com/..."/></label></div></section>
 <section className="panel p-5 sm:p-6"><h2 className="text-sm font-bold">Brand assets</h2><p className="mt-1 text-xs text-slate-400">Approved public URLs for the logo and browser icon.</p><div className="mt-4 grid gap-4 md:grid-cols-2">
 <label className="block text-xs font-semibold">School logo URL<input className="field mt-2" type="url" value={schoolSettings.logo_url} onChange={e=>updateSchoolSetting("logo_url",e.target.value)} placeholder="https://..."/></label>
 <label className="block text-xs font-semibold">Favicon URL<input className="field mt-2" type="url" value={schoolSettings.favicon_url} onChange={e=>updateSchoolSetting("favicon_url",e.target.value)} placeholder="https://..."/></label></div>
 {schoolSettings.logo_url&&<div className="mt-4 rounded-xl border border-slate-100 p-3"><p className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-slate-400">Logo preview</p><img src={schoolSettings.logo_url} alt="School logo preview" className="max-h-24 max-w-56 object-contain" onError={e=>{e.currentTarget.style.display="none"}}/></div>}</section>
 <div className="flex flex-col justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 sm:flex-row sm:items-center"><p className="text-xs leading-5 text-amber-900">Settings are saved securely but are not automatically published. Verify official details before publishing them on the public website.</p><button disabled={busy} type="submit" className="shrink-0 rounded-xl bg-[#542d80] px-5 py-3 text-xs font-semibold text-white disabled:opacity-50"><Save size={15} className="mr-2 inline"/>{busy?"Saving settings…":"Save school settings"}</button></div>
 </form>}
 <footer className="mt-8 flex flex-col justify-between gap-2 border-t border-slate-200/70 py-5 text-[10px] text-slate-400 sm:flex-row"><span>© 2026 Juneberries Schools · Every Child Matters. Every Potential Counts.</span><span className="flex items-center gap-1"><ShieldCheck size={12}/> Live secure administration workspace</span></footer>
 </main></div>
 {invite&&<div className="fixed inset-0 z-[70] grid place-items-center bg-[#21142e]/45 p-4 backdrop-blur-sm"><div className="w-full max-w-[470px] rounded-2xl bg-white p-6 shadow-2xl"><div className="flex justify-between"><div><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f8f5fc] text-[#693b9c]"><UserCheck size={19}/></div><h2 className="mt-4 text-lg font-bold">Invite a team member</h2><p className="mt-1 text-sm text-slate-500">Send a secure invitation to an authorised colleague.</p></div><button onClick={()=>setInvite(false)} className="text-slate-400"><X size={18}/></button></div><form className="mt-6 space-y-4" onSubmit={sendInvite}><label className="block text-xs font-semibold">Full name<input className="field mt-2" value={name} onChange={e=>setName(e.target.value)} required placeholder="Enter staff member's name"/></label><label className="block text-xs font-semibold">Work email<input className="field mt-2" type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="name@juneberriesschools.org"/></label><label className="block text-xs font-semibold">Assign role<select className="field mt-2" value={role} onChange={e=>setRole(e.target.value as RoleKey)}>{Object.entries(roleLabels).filter(([r])=>r!=="super_administrator").map(([r,l])=><option value={r} key={r}>{l}</option>)}</select></label><p className="rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-800">Super Administrator access cannot be assigned through staff invitations.</p><div className="flex justify-end gap-2 pt-2"><button type="button" onClick={()=>setInvite(false)} className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm">Cancel</button><button disabled={busy} className="rounded-xl bg-[#542d80] px-4 py-2.5 text-sm font-semibold text-white">{busy?"Sending…":<><Mail size={15} className="mr-2 inline"/> Send invitation</>}</button></div></form></div></div>}
 </div>;
}
function Status({status}:{status:StatusKey}){const style=status==="active"?"bg-emerald-50 text-emerald-700":status==="invited"?"bg-amber-50 text-amber-700":"bg-slate-100 text-slate-600";return <span className={"inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold "+style}><i className={"h-1.5 w-1.5 rounded-full "+(status==="active"?"bg-emerald-500":status==="invited"?"bg-amber-500":"bg-slate-400")}/>{statusLabels[status]}</span>}
